async function api(url,opt={}){opt.headers=Object.assign({'Content-Type':'application/json','X-CSRF-Token':csrf},opt.headers||{});let r=await fetch(url,opt);let j=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(j.error||'erro'),{status:r.status});return j}
function normalizeBarcode(v){return String(v||'').replace(/[\r\n]/g,'').trim()}
function requestDecimal(v){return String(v||'').trim().replace(',','.')}
function displayDecimal(v,max=3){let raw=String(v??'').trim();if(raw==='')return '';let n=Number(raw.replace(',','.'));if(!Number.isFinite(n))return raw;return new Intl.NumberFormat('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:max}).format(n)}
function movementErrorMessage(err){let m=String(err&&err.message||'').toLowerCase();if(m.includes('invalid request')||m.includes('validation'))return 'Revise os dados informados. Quantidade e custo devem ser valores válidos.';if(m.includes('estoque insuficiente'))return err.message;if(m.includes('resource not found')||m.includes('not found'))return 'Produto ou local não encontrado. Atualize a página e tente novamente.';if(m.includes('operation_id conflicts'))return 'Esta operação já foi enviada com dados diferentes. Revise os dados e tente novamente.';return 'Não foi possível concluir a operação. Tente novamente.'}
function cameraSupported(){return !!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia)}
function cameraMessage(err,stage){if(stage==='playback'&&err&&err.name==='NotAllowedError')return 'Não foi possível iniciar a visualização da câmera. Feche o leitor e tente novamente.';if(!cameraSupported())return 'Câmera não suportada neste navegador.';if(err&&err.name==='NotAllowedError')return 'Permissão da câmera negada. Libere o acesso à câmera nas configurações do navegador.';if(err&&err.name==='NotFoundError')return 'Nenhuma câmera foi encontrada neste dispositivo.';if(err&&err.name==='NotReadableError')return 'A câmera está sendo utilizada por outro aplicativo ou sessão.';if(err&&err.name==='OverconstrainedError')return 'Nenhuma câmera disponível.';return 'Não foi possível acessar a câmera.'}
