async function productLookup(q){q=normalizeBarcode(q);if(q.length<2)return[];return api('/api/products/lookup?q='+encodeURIComponent(q))}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function skuLabel(r){let item=r.item||'',brand=r.brand||'',barcode=r.barcode||'';let meta=[];if(brand&&brand!==item)meta.push(brand);if(barcode)meta.push('EAN '+barcode);return {item,meta:meta.join(' · ')}}
