function movementURL(path,d,x){let q=new URLSearchParams({sku_id:x.sku_id,item:d.name,brand:x.sku||'',barcode:x.barcode||'',unit:d.unit});if(x.warehouse_id)q.set('warehouse_id',x.warehouse_id);return path+'?'+q.toString()}
