async function load(){list.textContent='Carregando…';let qs='?show_zero='+(showZero&&showZero.checked?'1':'0')+(sel.value?'&warehouse_id='+sel.value:'');let rows=await api('/api/stock'+qs);list.textContent='';detail.hidden=true;detail.textContent='';openItem=null;rows.forEach(r=>{let d=document.createElement('button');d.type='button';d.className='row stock-card'+(r.below_minimum?' low':'');d.setAttribute('aria-expanded','false');let a=document.createElement('div');a.textContent=r.name;let sm=document.createElement('small');sm.textContent=(r.minimum?'Mínimo '+displayDecimal(r.minimum)+' '+r.unit:'Sem mínimo')+' · '+(sel.value?'local':'consolidado');a.append(sm);let b=document.createElement('strong');b.textContent=displayDecimal(r.quantity)+' '+r.unit+' ▼';d.append(a,b);d.onclick=()=>openDetail(r.item_id,d);d.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(r.item_id,d)}});list.append(d)})}
