initScanner('scanProduct',async code=>{productMsg('loading','Verificando código...');let rows=await productLookup(code).catch(()=>null);if(!rows){productMsg('error','Não foi possível consultar o código.');return}if(!rows.length){selected=null;document.getElementById('skuId').value='';productMsg('error','<strong>Código de barras não cadastrado.</strong><small>EAN: '+esc(normalizeBarcode(code))+'</small><button id="retryScan" class="secondary" type="button">Tentar novamente</button>');document.getElementById('retryScan')?.addEventListener('click',()=>scanBtn?.click());return}await pick(rows[0]);productMsg('success','<p>✓ Produto identificado</p>'+selectedHTML(rows[0]));document.getElementById('changeProduct')?.addEventListener('click',()=>{selected=null;document.getElementById('skuId').value='';search.value='';unit.textContent='';manualSeq++;clearLookup();productMsg('','');search.focus();summary()})});
