function renderParents(rows){list.textContent='';if(!rows.length){let p=document.createElement('p');p.className='hint';p.textContent='Nenhum item encontrado.';list.append(p);return}rows.forEach(r=>{let b=document.createElement('button');b.type='button';b.className='catalog-parent-card'+(currentItem&&+currentItem.id===+r.id?' selected':'');let strong=document.createElement('strong');strong.textContent=r.name;let small=document.createElement('small');small.textContent=parentMeta(r)+(r.active?'':' · Inativo');b.append(strong,small);b.onclick=()=>selectItem(r);list.append(b)})}
